// Grade 4-5 Social Studies missions. Adds to the subject defined in social.js.
window.SUBJECTS.social.missions.push(
  // ───────────────────────── GRADE 4: US REGIONS ─────────────────────────
  { id: 'soc45-regions', name: 'US Regions', icon: '🗺️', desc: 'Regions, landforms & map tools', grades: [4],
    learn: [
      { emoji: '🗺️', text: 'The United States is often split into five regions: the Northeast, Southeast, Midwest, Southwest and West.' },
      { emoji: '⛰️', text: 'The Rocky Mountains in the West are tall and rugged. The Appalachian Mountains in the East are much older, so wind and rain have worn them lower and rounder.' },
      { emoji: '🌾', text: 'The Great Plains are wide, flat grasslands in the middle of the country. Midwest and Plains farms grow lots of corn and wheat and raise cattle.' },
      { emoji: '🌊', text: 'The Mississippi River flows south from Minnesota to the Gulf of Mexico. The five Great Lakes are Superior, Michigan, Huron, Erie and Ontario. Lake Superior is the largest.' },
      { emoji: '🌦️', text: 'Climate differs by region: the Northeast has snowy winters, the Southeast is warm and humid, and the Southwest has hot, dry deserts. The West has everything from rainforests to deserts, and it includes Alaska and Hawaii.' },
      { emoji: '🦞', text: 'Resources differ too: Northeast lobster and maple syrup, Southeast citrus and cotton, Midwest corn, Southwest oil and copper, and West forests for lumber.' },
      { emoji: '🌐', text: 'Lines of latitude run east-west and tell how far north or south of the Equator (0°) a place is. Lines of longitude run north-south and are measured from the Prime Meridian (0°). The US is in the Northern and Western Hemispheres. A map scale shows how map distance compares to real distance.' },
    ],
    questions: [
      { id: 'soc45-regions-01', type: 'mc', q: 'Which region has the Grand Canyon and large, dry deserts?', choices: ['Northeast', 'Southwest', 'Midwest'], answer: 1, hint: 'Think of the region with the hottest, driest land and lots of cactus.', explain: 'The Southwest has deserts and the Grand Canyon in Arizona.', grades: [4], emoji: '🌵' },
      { id: 'soc45-regions-02', type: 'mc', q: 'Which tall, rugged mountains are in the western United States?', choices: ['Appalachian Mountains', 'Ozark Mountains', 'Rocky Mountains'], answer: 2, hint: 'They are the tallest of these ranges and run through Colorado.', explain: 'The Rocky Mountains stretch through the western US.', grades: [4], emoji: '🏔️' },
      { id: 'soc45-regions-03', type: 'mc', q: 'Which mountains in the East are very old and worn down lower and rounder?', choices: ['Appalachian Mountains', 'Rocky Mountains', 'Sierra Nevada'], answer: 0, hint: 'They run from Maine down toward Alabama, near the Atlantic side of the country.', explain: 'The Appalachians are old mountains that wind and rain have worn down.', grades: [4], emoji: '⛰️' },
      { id: 'soc45-regions-04', type: 'mc', q: 'Where does the Mississippi River end?', choices: ['The Pacific Ocean', 'Hudson Bay', 'Lake Superior', 'The Gulf of Mexico'], answer: 3, hint: 'The river flows south, all the way down to warm water near Louisiana.', explain: 'The Mississippi flows south and empties into the Gulf of Mexico.', grades: [4], emoji: '🌊' },
      { id: 'soc45-regions-05', type: 'mc', q: 'How many Great Lakes are there?', choices: ['3', '7', '5', '10'], answer: 2, hint: 'Try listing them: Superior, Michigan, Huron... and keep going.', explain: 'There are five Great Lakes: Superior, Michigan, Huron, Erie and Ontario.', grades: [4], emoji: '💧' },
      { id: 'soc45-regions-06', type: 'mc', q: 'Which Great Lake is the largest?', choices: ['Lake Erie', 'Lake Ontario', 'Lake Superior'], answer: 2, hint: 'Its name is a word that means "better" or "higher."', explain: 'Lake Superior is the largest of the Great Lakes.', grades: [4], emoji: '🏞️' },
      { id: 'soc45-regions-07', type: 'mc', q: 'The flat grasslands of the Great Plains are good for...', choices: ['Growing wheat and raising cattle', 'Skiing down steep slopes', 'Catching lobsters'], answer: 0, hint: 'Flat land with lots of grass is great for farms and ranches.', explain: 'The Great Plains are known for wheat farms and cattle ranches.', grades: [4], emoji: '🌾' },
      { id: 'soc45-regions-08', type: 'mc', q: 'Which region is famous for its flat farmland and huge corn crops?', choices: ['Southwest', 'Northeast', 'Midwest'], answer: 2, hint: 'Think of states like Iowa, Illinois and Nebraska in the middle of the country.', explain: 'The Midwest grows more corn than any other region.', grades: [4], emoji: '🌽' },
      { id: 'soc45-regions-09', type: 'mc', q: 'Which way do lines of latitude run?', choices: ['North to south (up and down)', 'East to west (side to side)'], answer: 1, hint: 'Some kids remember "latitude" by thinking of the flat rungs of a "ladder."', explain: 'Latitude lines run east-west and measure distance north or south of the Equator.', grades: [4], emoji: '🌐' },
      { id: 'soc45-regions-10', type: 'mc', q: 'What is the line at 0° latitude, around the middle of Earth, called?', choices: ['The Prime Meridian', 'The Equator', 'The Tropic of Cancer'], answer: 1, hint: 'It splits Earth into the Northern and Southern Hemispheres.', explain: 'The Equator is 0° latitude and divides Earth into Northern and Southern Hemispheres.', grades: [4], emoji: '🌍' },
      { id: 'soc45-regions-11', type: 'mc', q: 'Lines of longitude are measured east and west from which line?', choices: ['The Equator', 'The Arctic Circle', 'The Prime Meridian', 'The Tropic of Capricorn'], answer: 2, hint: 'This line is 0° longitude and runs from the North Pole to the South Pole.', explain: 'The Prime Meridian is 0° longitude.', grades: [4], emoji: '🧭' },
      { id: 'soc45-regions-12', type: 'mc', q: 'Which two hemispheres is the United States in?', choices: ['Northern and Western', 'Southern and Eastern', 'Northern and Eastern', 'Southern and Western'], answer: 0, hint: 'The US is above the Equator and to the left of the Prime Meridian on most maps.', explain: 'The US is north of the Equator and west of the Prime Meridian.', grades: [4], emoji: '🌎' },
      { id: 'soc45-regions-13', type: 'mc', q: 'On a map, 1 inch = 10 miles. Two towns are 3 inches apart. How far apart are they really?', choices: ['13 miles', '3 miles', '30 miles'], answer: 2, hint: 'Each inch stands for 10 miles. How many tens are in 3 inches?', explain: '3 inches × 10 miles = 30 miles.', grades: [4], emoji: '📏' },
      { id: 'soc45-regions-14', type: 'mc', q: 'What is the climate like in most of the Southeast?', choices: ['Freezing all year', 'Dry desert', 'Warm and humid'], answer: 2, hint: 'Think of Florida and Georgia in the summer: sticky air and lots of rain.', explain: 'The Southeast is mostly warm and humid, with long summers.', grades: [4], emoji: '☀️' },
      { id: 'soc45-regions-15', type: 'mc', q: 'Maple syrup and lobster fishing are famous in which region?', choices: ['Northeast', 'Southwest', 'Midwest'], answer: 0, hint: 'Think of Maine and Vermont along the cold Atlantic coast.', explain: 'The Northeast is known for maple syrup from Vermont and lobsters from Maine.', grades: [4], emoji: '🦞' },
      { id: 'soc45-regions-16', type: 'mc', q: 'Texas and Oklahoma in the Southwest are known for producing which resource?', choices: ['Maple syrup', 'Cranberries', 'Oil'], answer: 2, hint: 'This resource is pumped out of the ground and used to make fuel.', explain: 'The Southwest produces a lot of oil and natural gas.', grades: [4], emoji: '🛢️' },
      { id: 'soc45-regions-17', type: 'mc', q: 'Thick forests in Washington and Oregon make which region a big source of lumber?', choices: ['Midwest', 'West', 'Southwest'], answer: 1, hint: 'Washington and Oregon are on the Pacific Ocean.', explain: 'The West, especially the Pacific Northwest, has huge forests used for lumber.', grades: [4], emoji: '🌲' },
      { id: 'soc45-regions-18', type: 'mc', q: 'Florida and Georgia are in which region?', choices: ['Northeast', 'Midwest', 'West', 'Southeast'], answer: 3, hint: 'Find them in the bottom right corner of a US map.', explain: 'Florida and Georgia are in the Southeast.', grades: [4], emoji: '🍊' },
      { id: 'soc45-regions-19', type: 'mc', q: 'Which of these states is in the Midwest?', choices: ['Ohio', 'Arizona', 'Maine'], answer: 0, hint: 'One is a desert state, one is on the far northeast coast, and one is near the Great Lakes.', explain: 'Ohio is in the Midwest, near Lake Erie.', grades: [4], emoji: '🚜' },
      { id: 'soc45-regions-20', type: 'mc', q: 'Alaska and Hawaii belong to which region?', choices: ['Southeast', 'Northeast', 'West'], answer: 2, hint: 'Both are far from the Atlantic Ocean, out toward the Pacific.', explain: 'Alaska and Hawaii are part of the West region.', grades: [4], emoji: '🌺' },
    ],
  },

  // ───────────────────────── GRADE 4: NATIVE NATIONS ─────────────────────────
  { id: 'soc45-native', name: 'Native Nations', icon: '🪶', desc: 'Native peoples & their lands', grades: [4],
    learn: [
      { emoji: '🌎', text: 'Native peoples have lived in North America for thousands of years. There are hundreds of nations, each with its own language, government and traditions. Many nations continue today with their own governments.' },
      { emoji: '🌽', text: 'In the Northeast woodlands, the Haudenosaunee (Iroquois) live in longhouses traditionally and grow the "Three Sisters": corn, beans and squash. Their nations joined in a confederacy to keep peace and make decisions together. Woodland nations made wampum, shell beads used to record agreements.' },
      { emoji: '🦬', text: 'On the Great Plains, nations such as the Lakota, Cheyenne and Comanche traditionally followed bison herds. Tipis could be taken down and moved quickly, and almost every part of the bison was used for food, clothing and tools.' },
      { emoji: '🏜️', text: 'In the Southwest, Hopi, Zuni and other Pueblo peoples build homes of adobe, sun-dried bricks of mud and straw, and farm corn in dry land. The Diné (Navajo) traditionally live in round homes called hogans.' },
      { emoji: '🐟', text: 'In the Pacific Northwest, nations such as the Tlingit and Haida rely on salmon and use cedar trees for plank houses, canoes and carved totem poles. At a potlatch celebration, the host gives gifts to guests.' },
      { emoji: '✍️', text: 'In the Southeast, the Cherokee, Muscogee (Creek) and Seminole farmed in towns. A Cherokee man named Sequoyah created a writing system for the Cherokee language in 1821.' },
      { emoji: '🛶', text: 'In the Arctic, Inuit people hunt seals, travel in kayaks they invented, and built igloos of snow blocks as winter shelters while traveling. Nations everywhere traded with each other, swapping goods from their own environments.' },
    ],
    questions: [
      { id: 'soc45-native-01', type: 'mc', q: 'Which crops are called the "Three Sisters"?', choices: ['Corn, beans and squash', 'Wheat, rice and oats', 'Apples, pears and plums'], answer: 0, hint: 'These three crops grow together in one garden: one tall stalk, one climbing vine and one with big leaves.', explain: 'Corn, beans and squash were planted together and helped each other grow.', grades: [4], emoji: '🌽' },
      { id: 'soc45-native-02', type: 'mc', q: 'What kind of home did the Haudenosaunee traditionally build?', choices: ['Igloo', 'Longhouse', 'Adobe pueblo'], answer: 1, hint: 'Several families lived together in one long building made of wood and bark.', explain: 'Haudenosaunee families shared longhouses made of wooden poles and bark.', grades: [4], emoji: '🏠' },
      { id: 'soc45-native-03', type: 'mc', q: 'Plains nations like the Lakota traditionally depended on which animal?', choices: ['Salmon', 'Seal', 'Bison'], answer: 2, hint: 'Huge herds of this big, shaggy animal roamed the grasslands.', explain: 'The bison gave Plains nations food, clothing, tools and tipi covers.', grades: [4], emoji: '🦬' },
      { id: 'soc45-native-04', type: 'mc', q: 'Why were tipis a smart home for people who followed bison herds?', choices: ['They were easy to take down and move', 'They were built from stone', 'They were dug underground'], answer: 0, hint: 'The herds kept moving, so the people needed homes that could move too.', explain: 'Tipis could be packed up quickly and carried to a new camp.', grades: [4], emoji: '⛺' },
      { id: 'soc45-native-05', type: 'mc', q: 'What is adobe, used by Pueblo peoples to build homes?', choices: ['Cedar planks', 'Blocks of snow', 'Sun-dried bricks of mud and straw'], answer: 2, hint: 'The Southwest has lots of sunshine and earth, but few big trees.', explain: 'Adobe bricks are made of mud and straw dried in the sun.', grades: [4], emoji: '🧱' },
      { id: 'soc45-native-06', type: 'mc', q: 'Which food was most important to nations of the Pacific Northwest?', choices: ['Bison', 'Corn', 'Salmon'], answer: 2, hint: 'Rivers there fill with this fish every year.', explain: 'Salmon swimming up the rivers were a main food source.', grades: [4], emoji: '🐟' },
      { id: 'soc45-native-07', type: 'mc', q: 'Pacific Northwest nations used which tree to build plank houses and canoes?', choices: ['Cactus', 'Cedar', 'Palm'], answer: 1, hint: 'This tall tree grows in the rainy forests there and is easy to split into boards.', explain: 'Cedar wood was used for houses, canoes, totem poles and even clothing.', grades: [4], emoji: '🌲' },
      { id: 'soc45-native-08', type: 'mc', q: 'Which nations are known for carving tall totem poles?', choices: ['Pacific Northwest nations', 'Plains nations', 'Southwest Pueblo peoples'], answer: 0, hint: 'You need very tall trees to carve these.', explain: 'Nations like the Tlingit and Haida carve totem poles from cedar.', grades: [4], emoji: '🪵' },
      { id: 'soc45-native-09', type: 'mc', q: 'Sequoyah created a writing system for which nation\'s language?', choices: ['Hopi', 'Inuit', 'Cherokee'], answer: 2, hint: 'Sequoyah was from a Southeast nation.', explain: 'Sequoyah created a way to write the Cherokee language in 1821.', grades: [4], emoji: '✍️' },
      { id: 'soc45-native-10', type: 'mc', q: 'The Hopi and Zuni, Pueblo peoples, live in which region?', choices: ['Southwest', 'Pacific Northwest', 'Arctic'], answer: 0, hint: 'They farm corn in dry, sunny land.', explain: 'The Hopi, Zuni and other Pueblo peoples live in the Southwest.', grades: [4], emoji: '🏜️' },
      { id: 'soc45-native-11', type: 'mc', q: 'What small boat did the Inuit invent for hunting in icy waters?', choices: ['Steamboat', 'Sailboat', 'Kayak'], answer: 2, hint: 'It holds one person and is paddled with a double-ended paddle.', explain: 'The Inuit invented the kayak for hunting seals.', grades: [4], emoji: '🛶' },
      { id: 'soc45-native-12', type: 'mc', q: 'An igloo, built from blocks of snow, was mostly used as...', choices: ['A summer farmhouse', 'A trading post', 'A winter shelter while traveling and hunting'], answer: 2, hint: 'Snow blocks only last while it stays very cold.', explain: 'Igloos were winter shelters, often used during hunting trips.', grades: [4], emoji: '❄️' },
      { id: 'soc45-native-13', type: 'mc', q: 'Wampum, used by Northeast woodland nations, was made from what?', choices: ['Feathers', 'Shells', 'Copper'], answer: 1, hint: 'These small beads came from things found along the seashore.', explain: 'Wampum beads were made from shells and used to record agreements and events.', grades: [4], emoji: '🐚' },
      { id: 'soc45-native-14', type: 'mc', q: 'Why did the Haudenosaunee nations form a confederacy?', choices: ['To build a railroad', 'To sail to Europe', 'To keep peace and make decisions together'], answer: 2, hint: 'A confederacy is when separate groups join together as partners.', explain: 'The nations joined together to keep peace and decide important matters as a group.', grades: [4], emoji: '🤝' },
      { id: 'soc45-native-15', type: 'mc', q: 'Which is true about Native nations today?', choices: ['They all disappeared long ago', 'They all live in one state', 'Many continue today with their own governments, languages and traditions'], answer: 2, hint: 'Think about the word "continue."', explain: 'Hundreds of Native nations exist today across the United States.', grades: [4], emoji: '🌎' },
      { id: 'soc45-native-16', type: 'mc', q: 'What is the traditional round home of the Diné (Navajo) called?', choices: ['Longhouse', 'Plank house', 'Hogan'], answer: 2, hint: 'It is not made of bark or cedar boards; it is a round home of logs and earth.', explain: 'The Diné traditionally live in hogans, round homes of logs and earth.', grades: [4], emoji: '🏡' },
      { id: 'soc45-native-17', type: 'mc', q: 'Why did different nations build very different kinds of homes?', choices: ['They used materials from their own environment', 'They all bought homes from stores', 'A king told them how to build'], answer: 0, hint: 'Think about what is available: trees, snow, mud, or animal hides.', explain: 'Each nation used what its land offered, like cedar, adobe, snow or bison hides.', grades: [4], emoji: '🏗️' },
      { id: 'soc45-native-18', type: 'mc', q: 'A coastal nation swaps dried fish with an inland nation for animal hides. This is an example of...', choices: ['Taxes', 'Trade', 'Voting'], answer: 1, hint: 'Each side gives something and gets something back.', explain: 'Trading goods let nations get things their own lands did not provide.', grades: [4], emoji: '🔄' },
      { id: 'soc45-native-19', type: 'mc', q: 'At a potlatch, a Pacific Northwest celebration, the host...', choices: ['Hunts bison', 'Collects taxes', 'Gives gifts to the guests'], answer: 2, hint: 'This celebration is about generosity.', explain: 'At a potlatch, the host shares food and gives gifts to guests.', grades: [4], emoji: '🎁' },
      { id: 'soc45-native-20', type: 'mc', q: 'How long have Native peoples lived in North America?', choices: ['About 50 years', 'About 200 years', 'Thousands of years'], answer: 2, hint: 'They were here long, long before any European ships arrived.', explain: 'Native peoples have lived in North America for thousands of years.', grades: [4], emoji: '⏳' },
    ],
  },

  // ───────────────────────── GRADE 4: EXPLORERS ─────────────────────────
  { id: 'soc45-explorers', name: 'Age of Exploration', icon: '⛵', desc: 'Explorers, tools & voyages', grades: [4],
    learn: [
      { emoji: '💰', text: 'European explorers often sailed for the "three Gs": gold (riches), God (spreading their religion) and glory (fame). Many wanted a faster sea route to Asia for spices and silk.' },
      { emoji: '🧭', text: 'Sailors used a compass, whose magnetic needle points north, to find direction. An astrolabe measured the angle of the sun or stars to find latitude, how far north or south the ship was.' },
      { emoji: '⛵', text: 'In 1492, Christopher Columbus sailed for Spain with three ships: the Niña, the Pinta and the Santa María. He landed in the Caribbean but thought he had reached Asia.' },
      { emoji: '🛡️', text: 'Around the year 1000, Norse explorer Leif Erikson reached Newfoundland in North America, about 500 years before Columbus.' },
      { emoji: '🌍', text: 'Ferdinand Magellan\'s expedition (1519-1522) was the first to sail around the world. Magellan died on the way, and Juan Sebastián Elcano led the ship home. Ponce de León explored and named Florida for Spain (1513), Champlain founded Quebec for France (1608), and Henry Hudson explored the Hudson River for the Dutch (1609).' },
      { emoji: '🐎', text: 'The Columbian Exchange moved plants, animals and diseases between the Americas and Europe, Africa and Asia. Horses came to the Americas; corn, potatoes and tomatoes went to Europe.' },
      { emoji: '💔', text: 'Explorers claimed land where Native nations already lived. Diseases like smallpox, new to Native people\'s bodies, made huge numbers sick and many died. Some explorers also took land and forced people to work. Native nations resisted and adapted, and many continue today.' },
    ],
    questions: [
      { id: 'soc45-explorers-01', type: 'mc', q: 'Many European explorers were searching for a faster sea route to...', choices: ['Antarctica', 'Asia', 'The North Pole'], answer: 1, hint: 'They wanted spices and silk from faraway lands like India and China.', explain: 'Explorers hoped to reach Asia by sea to trade for spices and silk.', grades: [4], emoji: '🌶️' },
      { id: 'soc45-explorers-02', type: 'mc', q: 'What does a compass help sailors find?', choices: ['What time it is', 'How deep the water is', 'Which direction is north'], answer: 2, hint: 'Its needle is a tiny magnet.', explain: 'A compass needle points north, so sailors can tell their direction.', grades: [4], emoji: '🧭' },
      { id: 'soc45-explorers-03', type: 'mc', q: 'What did sailors use an astrolabe for?', choices: ['Measuring how fast the ship moved', 'Catching fish', 'Measuring the sun or stars to find latitude'], answer: 2, hint: 'Sailors pointed it at the sky.', explain: 'An astrolabe measured the angle of the sun or a star to find how far north or south the ship was.', grades: [4], emoji: '✨' },
      { id: 'soc45-explorers-04', type: 'mc', q: 'In what year did Columbus first sail across the Atlantic?', choices: ['1492', '1776', '1607', '1066'], answer: 0, hint: 'A rhyme says he "sailed the ocean blue" in fourteen hundred and...', explain: 'Columbus made his first voyage in 1492.', grades: [4], emoji: '📅' },
      { id: 'soc45-explorers-05', type: 'mc', q: 'Which country paid for Columbus\'s 1492 voyage?', choices: ['England', 'Spain', 'France'], answer: 1, hint: 'Its king and queen were Ferdinand and Isabella.', explain: 'Columbus sailed for Spain.', grades: [4], emoji: '👑' },
      { id: 'soc45-explorers-06', type: 'mc', q: 'Where did Columbus think he had landed?', choices: ['Africa', 'Antarctica', 'Asia'], answer: 2, hint: 'Remember where he was trying to go.', explain: 'Columbus believed he had reached Asia, but he was in the Caribbean.', grades: [4], emoji: '🏝️' },
      { id: 'soc45-explorers-07', type: 'mc', q: 'Which explorer reached North America about 500 years before Columbus?', choices: ['Leif Erikson', 'Henry Hudson', 'Ferdinand Magellan'], answer: 0, hint: 'He was a Norse explorer from around the year 1000.', explain: 'Leif Erikson reached Newfoundland around the year 1000.', grades: [4], emoji: '🛡️' },
      { id: 'soc45-explorers-08', type: 'mc', q: 'Magellan\'s expedition was the first to...', choices: ['Reach the North Pole', 'Find gold in California', 'Sail all the way around the world'], answer: 2, hint: 'It took about three years and ended back where it started.', explain: 'Magellan\'s expedition was the first to circle the globe.', grades: [4], emoji: '🌍' },
      { id: 'soc45-explorers-09', type: 'mc', q: 'Magellan died during his voyage. Who led the last ship home?', choices: ['Christopher Columbus', 'Leif Erikson', 'Juan Sebastián Elcano'], answer: 2, hint: 'The other two explorers lived at very different times.', explain: 'Juan Sebastián Elcano finished the trip around the world in 1522.', grades: [4], emoji: '🚢' },
      { id: 'soc45-explorers-10', type: 'mc', q: 'Which was NOT one of the "three Gs" of exploration?', choices: ['Gold', 'Glory', 'God', 'Games'], answer: 3, hint: 'The three Gs stood for riches, fame and religion.', explain: 'The three Gs were gold, God and glory.', grades: [4], emoji: '❓' },
      { id: 'soc45-explorers-11', type: 'mc', q: 'What was the Columbian Exchange?', choices: ['A bank Columbus started', 'The movement of plants, animals and diseases between the Americas and other continents', 'A trade of maps between sailors'], answer: 1, hint: 'Think about what crossed the ocean in both directions on ships.', explain: 'The Columbian Exchange moved crops, animals, people and diseases across the Atlantic.', grades: [4], emoji: '🔄' },
      { id: 'soc45-explorers-12', type: 'mc', q: 'Which animal did Europeans bring to the Americas?', choices: ['Turkey', 'Bison', 'Horse'], answer: 2, hint: 'Two of these animals already lived in North America.', explain: 'Horses came to the Americas from Europe and changed life for many nations.', grades: [4], emoji: '🐎' },
      { id: 'soc45-explorers-13', type: 'mc', q: 'Which food first came from the Americas and later spread to Europe?', choices: ['Wheat', 'Oranges', 'Potatoes'], answer: 2, hint: 'It grows underground and was first farmed in South America.', explain: 'Potatoes came from the Americas and became a key food in Europe.', grades: [4], emoji: '🥔' },
      { id: 'soc45-explorers-14', type: 'mc', q: 'Why did so many Native people get sick after Europeans arrived?', choices: ['Europeans brought diseases like smallpox that were new to them', 'The weather suddenly changed', 'They stopped eating vegetables'], answer: 0, hint: 'Germs traveled across the ocean too.', explain: 'Native people\'s bodies had never faced diseases like smallpox, so many became sick and died.', grades: [4], emoji: '💔' },
      { id: 'soc45-explorers-15', type: 'mc', q: 'Henry Hudson explored the river in New York that now has his name. Which country was he sailing for in 1609?', choices: ['The Netherlands (the Dutch)', 'Spain', 'Portugal'], answer: 0, hint: 'This country later started the colony of New Netherland there.', explain: 'Hudson sailed for the Dutch in 1609.', grades: [4], emoji: '🏞️' },
      { id: 'soc45-explorers-16', type: 'mc', q: 'Samuel de Champlain founded the city of Quebec for which country?', choices: ['Spain', 'France', 'England'], answer: 1, hint: 'People in Quebec still speak this country\'s language today.', explain: 'Champlain founded Quebec for France in 1608.', grades: [4], emoji: '🇫🇷' },
      { id: 'soc45-explorers-17', type: 'mc', q: 'Juan Ponce de León explored and named which present-day state?', choices: ['Maine', 'Oregon', 'Florida'], answer: 2, hint: 'He sailed for Spain in 1513 and landed on a warm peninsula in the Southeast.', explain: 'Ponce de León named Florida in 1513.', grades: [4], emoji: '🌸' },
      { id: 'soc45-explorers-18', type: 'mc', q: 'When explorers "claimed" land for their kings and queens, what was usually true?', choices: ['The land was empty', 'No one had ever seen it', 'Native nations already lived there'], answer: 2, hint: 'Remember who had lived in the Americas for thousands of years.', explain: 'Native nations already lived on the lands that explorers claimed.', grades: [4], emoji: '🏳️' },
      { id: 'soc45-explorers-19', type: 'mc', q: 'Which was one of Columbus\'s three ships in 1492?', choices: ['Mayflower', 'Santa María', 'Half Moon'], answer: 1, hint: 'The other two ships were the Niña and the Pinta.', explain: 'Columbus sailed with the Niña, the Pinta and the Santa María.', grades: [4], emoji: '⛵' },
    ],
  },

  // ───────────────────────── GRADE 4: ECONOMICS ─────────────────────────
  { id: 'soc45-economics', name: 'Money & Markets', icon: '💰', desc: 'Choices, prices, saving & trade', grades: [4],
    learn: [
      { emoji: '⚖️', text: 'Scarcity means there is not enough of something for everyone\'s wants. Because of scarcity, we have to make choices.' },
      { emoji: '🔀', text: 'Opportunity cost is the next-best thing you give up when you make a choice. If you spend your money on a book instead of a movie, the movie is your opportunity cost.' },
      { emoji: '📈', text: 'Supply is how much of something is for sale. Demand is how much people want it. When demand is high and supply is low, prices usually go up. When supply is high and demand is low, prices usually go down.' },
      { emoji: '🍋', text: 'An entrepreneur starts a business and takes a risk. Profit is the money left after paying costs. Producers make goods (things you can touch) or provide services (work done for others). Consumers buy them.' },
      { emoji: '📝', text: 'A budget is a plan for spending and saving. Income is money you earn. Expenses are money you spend.' },
      { emoji: '🏦', text: 'When you save money in a bank, the bank pays you interest, a little extra money for keeping your savings there. When people borrow, they pay interest.' },
      { emoji: '🚢', text: 'Specialization means focusing on making one thing well. People and countries specialize and then trade. Imports are goods brought into a country; exports are goods sent out. Trading goods without money is called bartering.' },
    ],
    questions: [
      { id: 'soc45-economics-01', type: 'mc', q: 'What does scarcity mean?', choices: ['Not having enough of something for everyone\'s wants', 'Having too much of everything', 'A scary story'], answer: 0, hint: 'It is the reason people have to make choices.', explain: 'Scarcity means resources are limited, so we must choose.', grades: [4], emoji: '⚖️' },
      { id: 'soc45-economics-02', type: 'mc', q: '{name} has $10 and can buy a book or a movie ticket. {name} picks the book. What is the opportunity cost?', choices: ['The book', 'The bookstore', 'The movie ticket'], answer: 2, hint: 'Opportunity cost is what you give up, not what you get.', explain: 'The movie ticket was the next-best choice that {name} gave up.', grades: [4], emoji: '🔀' },
      { id: 'soc45-economics-03', type: 'mc', q: 'A big snowstorm is coming. Everyone wants a snow shovel, but the store has only a few. What will probably happen to the price?', choices: ['It goes up', 'It goes down', 'It becomes free'], answer: 0, hint: 'Lots of people want something that there is very little of.', explain: 'High demand and low supply usually push prices up.', grades: [4], emoji: '❄️' },
      { id: 'soc45-economics-04', type: 'mc', q: 'Farmers grow way more strawberries than people want to buy. What will probably happen to the price?', choices: ['It goes up', 'It becomes free forever', 'It goes down'], answer: 2, hint: 'Sellers want to get rid of extra strawberries before they spoil.', explain: 'High supply and low demand usually push prices down.', grades: [4], emoji: '🍓' },
      { id: 'soc45-economics-05', type: 'mc', q: 'What is an entrepreneur?', choices: ['A kind of tax', 'A worker who prints money', 'A person who starts and runs a business'], answer: 2, hint: 'Think of a kid who opens a lemonade stand.', explain: 'An entrepreneur starts a business and takes a risk to make a profit.', grades: [4], emoji: '🍋' },
      { id: 'soc45-economics-06', type: 'mc', q: '{buddy}\'s lemonade stand earns $20. The lemons, sugar and cups cost $8. What is the profit?', choices: ['$28', '$12', '$8', '$20'], answer: 1, hint: 'Profit is what is left after you pay your costs. Subtract.', explain: '$20 earned − $8 costs = $12 profit.', grades: [4], emoji: '💵' },
      { id: 'soc45-economics-07', type: 'mc', q: 'What is a budget?', choices: ['A store coupon', 'A kind of bank', 'A plan for spending and saving money'], answer: 2, hint: 'You make one before you spend, to plan ahead.', explain: 'A budget is a plan for how to use your money.', grades: [4], emoji: '📝' },
      { id: 'soc45-economics-08', type: 'mc', q: 'In a budget, money you earn from a job or allowance is called...', choices: ['Expenses', 'Income', 'Interest'], answer: 1, hint: 'It is money coming "in."', explain: 'Income is money you earn.', grades: [4], emoji: '💼' },
      { id: 'soc45-economics-09', type: 'mc', q: 'Money you spend, like for food or rent, is called...', choices: ['Income', 'Profit', 'Expenses'], answer: 2, hint: 'This money goes out of your wallet.', explain: 'Expenses are the costs you pay.', grades: [4], emoji: '🧾' },
      { id: 'soc45-economics-10', type: 'mc', q: '{name} saves $100 in a bank. The bank pays $5 of interest per year for every $100 saved. How much will {name} have after one year?', choices: ['$95', '$100', '$105', '$150'], answer: 2, hint: 'Interest is added to your savings, not taken away.', explain: '$100 + $5 interest = $105.', grades: [4], emoji: '🏦' },
      { id: 'soc45-economics-11', type: 'mc', q: 'What is interest on a savings account?', choices: ['Extra money the bank pays you for saving', 'A fee for walking into the bank', 'A hobby you enjoy'], answer: 0, hint: 'It makes your savings grow over time.', explain: 'Banks pay interest to people who keep savings with them.', grades: [4], emoji: '🌱' },
      { id: 'soc45-economics-12', type: 'mc', q: 'Getting a haircut is an example of...', choices: ['A good', 'A natural resource', 'A service'], answer: 2, hint: 'You do not take home an object; someone does work for you.', explain: 'A haircut is a service, work done for someone else.', grades: [4], emoji: '💇' },
      { id: 'soc45-economics-13', type: 'mc', q: 'Which of these is a good?', choices: ['A haircut', 'A music lesson', 'A bicycle'], answer: 2, hint: 'A good is something you can touch and keep.', explain: 'A bicycle is a good, an object made and sold.', grades: [4], emoji: '🚲' },
      { id: 'soc45-economics-14', type: 'mc', q: 'A baker only bakes bread and buys everything else from others. This is called...', choices: ['Scarcity', 'Specialization', 'Interest'], answer: 1, hint: 'The baker focuses on one "special" job.', explain: 'Specialization is focusing on making one thing well.', grades: [4], emoji: '🍞' },
      { id: 'soc45-economics-15', type: 'mc', q: 'Why do countries trade with each other?', choices: ['Trading is required for every item', 'To get rid of all their money', 'To get goods they cannot make as easily or cheaply themselves'], answer: 2, hint: 'Think about bananas: can every country grow them?', explain: 'Countries specialize and trade to get things they cannot make as well.', grades: [4], emoji: '🚢' },
      { id: 'soc45-economics-16', type: 'mc', q: 'Bananas grown in another country and shipped into the US are a US...', choices: ['Export', 'Import', 'Tax'], answer: 1, hint: 'These goods are coming "in" to the country.', explain: 'Imports are goods brought into a country.', grades: [4], emoji: '🍌' },
      { id: 'soc45-economics-17', type: 'mc', q: 'When you buy a sandwich at a deli, you are a...', choices: ['Producer', 'Entrepreneur', 'Consumer'], answer: 2, hint: 'You are the one buying and eating, not making.', explain: 'A consumer buys and uses goods and services.', grades: [4], emoji: '🥪' },
      { id: 'soc45-economics-18', type: 'mc', q: 'Trading your apple for a friend\'s orange without using money is called...', choices: ['Bartering', 'Budgeting', 'Borrowing'], answer: 0, hint: 'This is the oldest kind of trade, from before coins existed.', explain: 'Bartering is trading goods or services directly, without money.', grades: [4], emoji: '🍎' },
      { id: 'soc45-economics-19', type: 'mc', q: 'Why is starting a business a risk?', choices: ['Businesses always make money', 'Risk is a kind of paperwork', 'The business might lose money'], answer: 2, hint: 'A risk is a chance that something will not work out.', explain: 'Entrepreneurs risk losing the money they put into their business.', grades: [4], emoji: '🎲' },
      { id: 'soc45-economics-20', type: 'mc', q: '{name} wants a $30 game and saves $5 each week. How many weeks will it take?', choices: ['5', '6', '10', '3'], answer: 1, hint: 'How many groups of $5 make $30?', explain: '$30 ÷ $5 = 6 weeks.', grades: [4], emoji: '🎮' },
    ],
  },

  // ───────────────────────── GRADE 5: 13 COLONIES ─────────────────────────
  { id: 'soc45-colonies', name: 'The 13 Colonies', icon: '🏘️', desc: 'Colonial life & regions', grades: [5],
    learn: [
      { emoji: '🗺️', text: 'England had 13 colonies along the Atlantic coast in three regions. New England: Massachusetts, New Hampshire, Connecticut, Rhode Island. Middle: New York, New Jersey, Pennsylvania, Delaware. Southern: Maryland, Virginia, North Carolina, South Carolina, Georgia (the last, founded in 1732).' },
      { emoji: '⚓', text: 'Jamestown, Virginia (1607) was the first lasting English settlement. Early years were very hard. It survived after colonists began growing tobacco to sell, which became its cash crop. The Powhatan people already lived there.' },
      { emoji: '⛪', text: 'In 1620 the Pilgrims sailed on the Mayflower to practice their religion freely and founded Plymouth. They signed the Mayflower Compact, agreeing to make fair laws and follow them. The Wampanoag leader Massasoit made an agreement with them, and Tisquantum (Squanto) helped them grow corn.' },
      { emoji: '🐳', text: 'New England had rocky soil and cold winters, so people fished, built ships and cut lumber. Towns held town meetings to vote on local issues. Roger Williams founded Rhode Island as a place to worship freely.' },
      { emoji: '🌾', text: 'The Middle colonies had rich soil and grew so much wheat they were called the "breadbasket colonies." William Penn, a Quaker, founded Pennsylvania, welcoming many religions. Philadelphia and New York City became busy ports.' },
      { emoji: '☀️', text: 'The Southern colonies had a warm climate and long growing season. Large farms called plantations grew tobacco, rice and indigo.' },
      { emoji: '⛓️', text: 'Enslaved Africans were taken from their homes and forced to work without pay or freedom. Slavery existed in all 13 colonies, but most enslaved people lived in the Southern colonies. They kept their cultures and families alive as best they could and resisted in many ways. Colonists and Native nations traded and sometimes helped each other, but as colonists took more land, conflicts grew.' },
    ],
    questions: [
      { id: 'soc45-colonies-01', type: 'mc', q: 'How many English colonies became the first United States?', choices: ['10', '50', '13'], answer: 2, hint: 'Count the stripes on the US flag.', explain: 'There were 13 colonies, which is why the flag has 13 stripes.', grades: [5], emoji: '🇺🇸' },
      { id: 'soc45-colonies-02', type: 'mc', q: 'In what year was Jamestown founded?', choices: ['1620', '1776', '1607', '1492'], answer: 2, hint: 'It came 13 years before the Mayflower landed.', explain: 'Jamestown was founded in 1607.', grades: [5], emoji: '📅' },
      { id: 'soc45-colonies-03', type: 'mc', q: 'Jamestown was in which present-day state?', choices: ['Massachusetts', 'Virginia', 'New York'], answer: 1, hint: 'It is a Southern colony on the Chesapeake Bay.', explain: 'Jamestown was in Virginia.', grades: [5], emoji: '⚓' },
      { id: 'soc45-colonies-04', type: 'mc', q: 'What ship carried the Pilgrims to Plymouth in 1620?', choices: ['Mayflower', 'Santa María', 'Half Moon'], answer: 0, hint: 'Its name includes a spring blossom.', explain: 'The Pilgrims sailed on the Mayflower.', grades: [5], emoji: '⛵' },
      { id: 'soc45-colonies-05', type: 'mc', q: 'Why did the Pilgrims come to America?', choices: ['To search for gold', 'To find a route to Asia', 'To practice their religion freely'], answer: 2, hint: 'They had been punished in England for how they worshipped.', explain: 'The Pilgrims wanted religious freedom.', grades: [5], emoji: '⛪' },
      { id: 'soc45-colonies-06', type: 'mc', q: 'The leader Massasoit, who made an agreement with the Plymouth colonists, belonged to which nation?', choices: ['Lakota', 'Hopi', 'Wampanoag'], answer: 2, hint: 'This nation lived in what is now Massachusetts, not on the Plains or in the desert.', explain: 'Massasoit was a leader of the Wampanoag.', grades: [5], emoji: '🤝' },
      { id: 'soc45-colonies-07', type: 'mc', q: 'What was the Mayflower Compact?', choices: ['An agreement to make fair laws together and follow them', 'A map of the ocean', 'A treaty ending a war'], answer: 0, hint: 'A "compact" is a kind of promise or agreement.', explain: 'The Pilgrims agreed to govern themselves with fair laws.', grades: [5], emoji: '📜' },
      { id: 'soc45-colonies-08', type: 'mc', q: 'Which cash crop helped Jamestown survive and grow?', choices: ['Wheat', 'Tobacco', 'Apples'], answer: 1, hint: 'Its leaves were dried and sold in England.', explain: 'Tobacco became the cash crop that made Virginia profitable.', grades: [5], emoji: '🍂' },
      { id: 'soc45-colonies-09', type: 'mc', q: 'Rocky soil and cold winters led many New Englanders to earn a living by...', choices: ['Growing rice', 'Growing tobacco on plantations', 'Fishing and building ships'], answer: 2, hint: 'Farming was hard there, so they turned to the sea and forests.', explain: 'New Englanders fished, whaled, built ships and cut lumber.', grades: [5], emoji: '🐳' },
      { id: 'soc45-colonies-10', type: 'mc', q: 'Which colonies were called the "breadbasket colonies"?', choices: ['New England colonies', 'Middle colonies', 'Southern colonies'], answer: 1, hint: 'Bread is made from wheat. Which region grew the most wheat?', explain: 'The Middle colonies grew lots of wheat and other grains.', grades: [5], emoji: '🍞' },
      { id: 'soc45-colonies-11', type: 'mc', q: 'William Penn, a Quaker, founded which colony?', choices: ['Pennsylvania', 'Georgia', 'Virginia'], answer: 0, hint: 'It is a Middle colony with the big city of Philadelphia.', explain: 'William Penn founded Pennsylvania in 1681.', grades: [5], emoji: '🕊️' },
      { id: 'soc45-colonies-12', type: 'mc', q: 'Why did large plantations grow in the Southern colonies?', choices: ['Rocky soil', 'Very short summers', 'A warm climate and long growing season'], answer: 2, hint: 'Crops like rice need lots of warm days.', explain: 'Warm weather and a long growing season suited big crops like tobacco and rice.', grades: [5], emoji: '☀️' },
      { id: 'soc45-colonies-13', type: 'mc', q: 'Which of these was a New England colony?', choices: ['Massachusetts', 'Georgia', 'Pennsylvania'], answer: 0, hint: 'Plymouth was in this colony.', explain: 'Massachusetts was a New England colony.', grades: [5], emoji: '🍂' },
      { id: 'soc45-colonies-14', type: 'mc', q: 'Which of these was a Southern colony?', choices: ['New York', 'Connecticut', 'South Carolina'], answer: 2, hint: 'Pick the colony farthest south of these three.', explain: 'South Carolina was one of the Southern colonies.', grades: [5], emoji: '🌴' },
      { id: 'soc45-colonies-15', type: 'mc', q: 'Enslaved Africans in the colonies were...', choices: ['Paid workers who could quit', 'Colonists seeking religious freedom', 'Forced to work without pay or freedom'], answer: 2, hint: 'Being enslaved means having no choice and no freedom.', explain: 'Enslaved people were forced to work and were denied their freedom.', grades: [5], emoji: '⛓️' },
      { id: 'soc45-colonies-16', type: 'mc', q: 'Slavery existed in all 13 colonies. In which region did most enslaved people live?', choices: ['New England', 'Middle colonies', 'Southern colonies'], answer: 2, hint: 'Think about where the large plantations were.', explain: 'Most enslaved people were forced to work on Southern plantations.', grades: [5], emoji: '🗺️' },
      { id: 'soc45-colonies-17', type: 'mc', q: 'Which was the last of the 13 colonies to be founded?', choices: ['Virginia', 'Georgia', 'Massachusetts'], answer: 1, hint: 'It was the farthest south, founded in 1732.', explain: 'Georgia was founded last, in 1732.', grades: [5], emoji: '🍑' },
      { id: 'soc45-colonies-18', type: 'mc', q: 'As more colonists arrived and took land, relations with many Native nations...', choices: ['Often turned into conflict', 'Always stayed peaceful', 'Did not change at all'], answer: 0, hint: 'Think about how people feel when their homeland is taken.', explain: 'Trade and help happened, but taking land led to many conflicts.', grades: [5], emoji: '⚖️' },
      { id: 'soc45-colonies-19', type: 'mc', q: 'In New England towns, colonists gathered at ___ to vote on local issues.', choices: ['Plantations', 'Trading posts', 'Town meetings'], answer: 2, hint: 'Everyone in town came together in one place to decide.', explain: 'Town meetings let colonists make local decisions together.', grades: [5], emoji: '🗳️' },
      { id: 'soc45-colonies-20', type: 'mc', q: 'Roger Williams founded which colony as a place where people could worship freely?', choices: ['Georgia', 'New Jersey', 'Rhode Island'], answer: 2, hint: 'It is the smallest colony, in New England.', explain: 'Roger Williams founded Rhode Island in 1636.', grades: [5], emoji: '⛪' },
    ],
  },

  // ───────────────────────── GRADE 5: REVOLUTION ─────────────────────────
  { id: 'soc45-revolution', name: 'The American Revolution', icon: '🔔', desc: 'Road to independence', grades: [5],
    learn: [
      { emoji: '💷', text: 'After the French and Indian War (1754-1763), Britain had large debts. Parliament taxed the colonies to help pay. King George III ruled Britain.' },
      { emoji: '📜', text: 'The Stamp Act (1765) taxed printed paper like newspapers and documents. Colonists had no representatives in Parliament, so they said, "No taxation without representation!" Many boycotted, refusing to buy British goods.' },
      { emoji: '🫖', text: 'On December 16, 1773, colonists in the Boston Tea Party dumped British tea into Boston Harbor to protest a tax law. Britain punished Boston by closing its harbor.' },
      { emoji: '🏇', text: 'In April 1775, Paul Revere and others rode at night to warn that British soldiers were coming. The first battles of the war happened at Lexington and Concord. Colonists who wanted independence were Patriots; those loyal to the king were Loyalists.' },
      { emoji: '✒️', text: 'The Declaration of Independence was adopted on July 4, 1776. Thomas Jefferson wrote most of it; John Adams and Benjamin Franklin helped. It says all men are created equal, with rights to life, liberty and the pursuit of happiness, and that government gets its power from the consent of the people.' },
      { emoji: '⚖️', text: 'In 1776 those rights were not given to everyone: enslaved people, women and Native Americans were left out. Americans have worked ever since to extend those rights to all.' },
      { emoji: '🎖️', text: 'George Washington led the Continental Army. Franklin won the help of France. The British surrendered at Yorktown in 1781, and the Treaty of Paris (1783) recognized the United States as independent.' },
    ],
    questions: [
      { id: 'soc45-revolution-01', type: 'mc', q: 'Why did Britain start taxing the colonies in the 1760s?', choices: ['To build a castle in Boston', 'To pay debts from the French and Indian War', 'To pay for colonial schools'], answer: 1, hint: 'Wars are very expensive, and one had just ended.', explain: 'Britain needed money to pay for the French and Indian War.', grades: [5], emoji: '💷' },
      { id: 'soc45-revolution-02', type: 'mc', q: 'What did the Stamp Act tax?', choices: ['Printed paper like newspapers and documents', 'Only tea', 'Horses'], answer: 0, hint: 'A stamp was placed on things made of paper to show the tax was paid.', explain: 'The Stamp Act taxed newspapers, legal papers and even playing cards.', grades: [5], emoji: '📰' },
      { id: 'soc45-revolution-03', type: 'mc', q: 'What did "No taxation without representation" mean?', choices: ['Nobody should ever pay taxes', 'Only kings may make laws', 'Colonists should not be taxed by a Parliament where they had no representatives'], answer: 2, hint: 'Colonists could not vote for anyone in Parliament.', explain: 'Colonists wanted a voice in the government that taxed them.', grades: [5], emoji: '📢' },
      { id: 'soc45-revolution-04', type: 'mc', q: 'In what year was the Boston Tea Party?', choices: ['1607', '1787', '1776', '1773'], answer: 3, hint: 'It was a few years before the Declaration of Independence.', explain: 'The Boston Tea Party happened on December 16, 1773.', grades: [5], emoji: '🫖' },
      { id: 'soc45-revolution-05', type: 'mc', q: 'What happened at the Boston Tea Party?', choices: ['Colonists dumped British tea into the harbor to protest a tax', 'A fancy party with tea and cake', 'A sea battle between ships'], answer: 0, hint: 'It was a protest, not a celebration.', explain: 'Colonists threw chests of tea into Boston Harbor to protest British tax laws.', grades: [5], emoji: '📦' },
      { id: 'soc45-revolution-06', type: 'mc', q: 'When colonists refused to buy British goods, it was called a...', choices: ['Ballot', 'Boycott', 'Budget'], answer: 1, hint: 'It is a peaceful protest where people stop buying something.', explain: 'A boycott is refusing to buy goods as a protest.', grades: [5], emoji: '🚫' },
      { id: 'soc45-revolution-07', type: 'mc', q: 'What is Paul Revere famous for?', choices: ['Writing the Declaration', 'Being the first president', 'Riding at night to warn that British soldiers were coming'], answer: 2, hint: 'A famous poem tells about his midnight ride.', explain: 'Paul Revere rode to warn colonists in April 1775.', grades: [5], emoji: '🏇' },
      { id: 'soc45-revolution-08', type: 'mc', q: 'Where were the first battles of the Revolution fought in 1775?', choices: ['Yorktown', 'Plymouth', 'Lexington and Concord'], answer: 2, hint: 'These two towns are near Boston, where Paul Revere rode.', explain: 'The war began at Lexington and Concord, Massachusetts.', grades: [5], emoji: '🔔' },
      { id: 'soc45-revolution-09', type: 'mc', q: 'When was the Declaration of Independence adopted?', choices: ['December 16, 1773', 'July 4, 1776', 'September 17, 1787'], answer: 1, hint: 'Americans celebrate this date with fireworks every summer.', explain: 'The Declaration was adopted on July 4, 1776.', grades: [5], emoji: '🎆' },
      { id: 'soc45-revolution-10', type: 'mc', q: 'Who wrote most of the Declaration of Independence?', choices: ['Paul Revere', 'George Washington', 'Thomas Jefferson'], answer: 2, hint: 'He was a young Virginian and later became the third president.', explain: 'Thomas Jefferson wrote most of the Declaration.', grades: [5], emoji: '✒️' },
      { id: 'soc45-revolution-11', type: 'mc', q: 'The Declaration says people have rights to life, liberty and the pursuit of...', choices: ['Happiness', 'Money', 'Land'], answer: 0, hint: 'It is about being able to seek a good, joyful life.', explain: '"Life, liberty and the pursuit of happiness."', grades: [5], emoji: '😊' },
      { id: 'soc45-revolution-12', type: 'mc', q: 'The Declaration says a government gets its power from...', choices: ['The king', 'The strongest army', 'The consent of the people it governs'], answer: 2, hint: 'Who should agree to be governed?', explain: 'Governments get their power from the consent of the governed.', grades: [5], emoji: '🗳️' },
      { id: 'soc45-revolution-13', type: 'mc', q: 'Who led the Continental Army?', choices: ['Benjamin Franklin', 'George Washington', 'John Adams'], answer: 1, hint: 'He later became the first president.', explain: 'George Washington commanded the Continental Army.', grades: [5], emoji: '🎖️' },
      { id: 'soc45-revolution-14', type: 'mc', q: 'Benjamin Franklin traveled to which country to win its help for the Patriots?', choices: ['Russia', 'Mexico', 'France'], answer: 2, hint: 'This country was Britain\'s old rival and later sent ships and soldiers.', explain: 'Franklin convinced France to help the Patriots.', grades: [5], emoji: '🤝' },
      { id: 'soc45-revolution-15', type: 'mc', q: 'Where did the British army surrender in 1781?', choices: ['Yorktown', 'Lexington', 'Boston'], answer: 0, hint: 'It was in Virginia, near the end of the war, not where it started.', explain: 'The British surrendered at Yorktown, Virginia, in 1781.', grades: [5], emoji: '🏳️' },
      { id: 'soc45-revolution-16', type: 'mc', q: 'Which 1783 agreement officially ended the war and recognized US independence?', choices: ['The Mayflower Compact', 'The Stamp Act', 'The Treaty of Paris'], answer: 2, hint: 'It was signed in a European capital city.', explain: 'The Treaty of Paris (1783) ended the Revolutionary War.', grades: [5], emoji: '📜' },
      { id: 'soc45-revolution-17', type: 'mc', q: 'Colonists who stayed loyal to the British king were called...', choices: ['Patriots', 'Loyalists', 'Pilgrims'], answer: 1, hint: 'Patriots wanted independence. These colonists did not.', explain: 'Loyalists supported the king; Patriots wanted independence.', grades: [5], emoji: '👑' },
      { id: 'soc45-revolution-18', type: 'mc', q: 'John Adams and Benjamin Franklin worked with Jefferson to...', choices: ['Sail the Mayflower', 'Dump the tea', 'Prepare the Declaration of Independence'], answer: 2, hint: 'They were on a committee in Philadelphia in 1776.', explain: 'Adams and Franklin helped Jefferson prepare the Declaration.', grades: [5], emoji: '🖋️' },
      { id: 'soc45-revolution-19', type: 'mc', q: 'When the Declaration said "all men are created equal" in 1776, which was true?', choices: ['Everyone already had equal rights', 'Only children had rights', 'Those rights were not yet given to everyone, such as enslaved people and women'], answer: 2, hint: 'Remember who was left out at the time.', explain: 'Many people were left out in 1776; Americans worked for generations to extend those rights.', grades: [5], emoji: '⚖️' },
      { id: 'soc45-revolution-20', type: 'mc', q: 'Who was the king of Great Britain during the American Revolution?', choices: ['King George III', 'King Henry VIII', 'King Arthur'], answer: 0, hint: 'His name has a Roman numeral that means "the third."', explain: 'King George III ruled Britain during the Revolution.', grades: [5], emoji: '👑' },
    ],
  },

  // ───────────────────────── GRADE 5: CONSTITUTION ─────────────────────────
  { id: 'soc45-constitution', name: 'The Constitution', icon: '📜', desc: 'Government, rights & citizens', grades: [5],
    learn: [
      { emoji: '🧩', text: 'The first plan of government, the Articles of Confederation, made the national government too weak. It could not collect taxes, had no president and no national courts.' },
      { emoji: '🏛️', text: 'In 1787, leaders met in Philadelphia at the Constitutional Convention to write a new plan. George Washington led the meeting, and James Madison is called the "Father of the Constitution." It begins with the words "We the People."' },
      { emoji: '🌳', text: 'The Constitution creates three branches. The legislative branch (Congress: the Senate and the House of Representatives) makes laws. The executive branch (the President) carries out laws. The judicial branch (the Supreme Court and other courts) decides what laws mean.' },
      { emoji: '⚖️', text: 'Checks and balances keep any one branch from getting too powerful. The President can veto (reject) a bill. Congress can override a veto with a two-thirds vote in both houses. Courts can decide a law goes against the Constitution.' },
      { emoji: '🗽', text: 'The Bill of Rights is the first 10 amendments (changes) to the Constitution, added in 1791. The First Amendment protects freedom of speech, religion, the press, peaceful assembly and petition. Other amendments protect the right to a fair trial by jury.' },
      { emoji: '🏢', text: 'Federalism means power is shared between the national government and state governments. The national government prints money and makes treaties. States issue driver\'s licenses and run public schools.' },
      { emoji: '🙋', text: 'Citizens have rights, such as voting at age 18, and responsibilities, such as obeying laws, paying taxes, serving on a jury and staying informed.' },
    ],
    questions: [
      { id: 'soc45-constitution-01', type: 'mc', q: 'What was a big problem with the Articles of Confederation?', choices: ['The king had too much power', 'The national government was too weak and could not collect taxes', 'There were too many presidents'], answer: 1, hint: 'After the Revolution, Americans were afraid of a strong ruler, so they went too far the other way.', explain: 'The Articles made a national government too weak to do its job.', grades: [5], emoji: '🧩' },
      { id: 'soc45-constitution-02', type: 'mc', q: 'Where and when was the Constitutional Convention held?', choices: ['Boston in 1773', 'Jamestown in 1607', 'Philadelphia in 1787'], answer: 2, hint: 'It was in the same city as the Declaration, eleven years later.', explain: 'The Convention met in Philadelphia in 1787.', grades: [5], emoji: '🏛️' },
      { id: 'soc45-constitution-03', type: 'mc', q: 'Who is called the "Father of the Constitution"?', choices: ['James Madison', 'Paul Revere', 'Christopher Columbus'], answer: 0, hint: 'He planned much of the new government and later became the fourth president.', explain: 'James Madison shaped many of the Constitution\'s ideas.', grades: [5], emoji: '✍️' },
      { id: 'soc45-constitution-04', type: 'mc', q: 'Which branch of government makes laws?', choices: ['Executive', 'Judicial', 'Legislative'], answer: 2, hint: 'This branch is Congress.', explain: 'The legislative branch, Congress, makes laws.', grades: [5], emoji: '📝' },
      { id: 'soc45-constitution-05', type: 'mc', q: 'Who leads the executive branch?', choices: ['The Supreme Court', 'Congress', 'The President'], answer: 2, hint: 'This branch carries out the laws, led by one person.', explain: 'The President leads the executive branch.', grades: [5], emoji: '🏠' },
      { id: 'soc45-constitution-06', type: 'mc', q: 'The Supreme Court is part of which branch?', choices: ['Legislative', 'Judicial', 'Executive'], answer: 1, hint: 'Judges work in this branch.', explain: 'The Supreme Court leads the judicial branch.', grades: [5], emoji: '⚖️' },
      { id: 'soc45-constitution-07', type: 'mc', q: 'What are the two parts of Congress?', choices: ['The Senate and the House of Representatives', 'The Supreme Court and the President', 'Governors and mayors'], answer: 0, hint: 'Both parts work in the Capitol building and vote on bills.', explain: 'Congress is made of the Senate and the House of Representatives.', grades: [5], emoji: '🏛️' },
      { id: 'soc45-constitution-08', type: 'mc', q: 'When the President rejects a bill passed by Congress, it is called a...', choices: ['Verdict', 'Vote', 'Veto'], answer: 2, hint: 'The word comes from Latin for "I forbid."', explain: 'A veto is the President\'s rejection of a bill.', grades: [5], emoji: '✋' },
      { id: 'soc45-constitution-09', type: 'mc', q: 'Why does the Constitution have checks and balances?', choices: ['So laws are made faster', 'So the President can do anything', 'So no one branch becomes too powerful'], answer: 2, hint: 'Each branch can "check" the others.', explain: 'Checks and balances keep power spread among the three branches.', grades: [5], emoji: '⚖️' },
      { id: 'soc45-constitution-10', type: 'mc', q: 'If the President vetoes a bill, Congress can still make it a law with...', choices: ['A two-thirds vote in both houses', 'One senator\'s vote', 'Permission from a king'], answer: 0, hint: 'It takes much more than a simple majority.', explain: 'Congress can override a veto with a two-thirds vote in the Senate and the House.', grades: [5], emoji: '🔁' },
      { id: 'soc45-constitution-11', type: 'mc', q: 'What is the Bill of Rights?', choices: ['A list of taxes', 'The first 10 amendments to the Constitution', 'The Declaration of Independence'], answer: 1, hint: 'It was added in 1791 to protect people\'s freedoms.', explain: 'The Bill of Rights is the first ten amendments.', grades: [5], emoji: '🗽' },
      { id: 'soc45-constitution-12', type: 'mc', q: 'Which freedom does the First Amendment protect?', choices: ['The right to skip school', 'The right to drive at age 10', 'Freedom of speech'], answer: 2, hint: 'It protects saying what you think.', explain: 'The First Amendment protects speech, religion, press, assembly and petition.', grades: [5], emoji: '🗣️' },
      { id: 'soc45-constitution-13', type: 'mc', q: 'A newspaper prints a report that criticizes the government. Which freedom protects this?', choices: ['Freedom of the press', 'Freedom of religion', 'The right to a jury trial'], answer: 0, hint: 'Newspapers were printed on printing presses.', explain: 'Freedom of the press lets newspapers report freely.', grades: [5], emoji: '📰' },
      { id: 'soc45-constitution-14', type: 'mc', q: 'The right to a fair trial by jury protects people who are...', choices: ['Running for office', 'Accused of a crime', 'Starting a business'], answer: 1, hint: 'Juries decide cases in court.', explain: 'People accused of crimes have the right to a fair trial by jury.', grades: [5], emoji: '👩‍⚖️' },
      { id: 'soc45-constitution-15', type: 'mc', q: 'What is federalism?', choices: ['One person ruling everything', 'Having no government', 'Sharing power between the national and state governments'], answer: 2, hint: 'Think of the national government and the 50 state governments working at the same time.', explain: 'Federalism divides power between national and state governments.', grades: [5], emoji: '🏢' },
      { id: 'soc45-constitution-16', type: 'mc', q: 'Which job belongs to the national (federal) government?', choices: ['Issuing driver\'s licenses', 'Running a town library', 'Printing money'], answer: 2, hint: 'This must be the same in every state so it works everywhere.', explain: 'Only the national government prints money.', grades: [5], emoji: '💵' },
      { id: 'soc45-constitution-17', type: 'mc', q: 'Which job is usually done by state governments?', choices: ['Issuing driver\'s licenses', 'Printing money', 'Making treaties with other countries'], answer: 0, hint: 'Grown-ups get this card from an office in their own state.', explain: 'States issue driver\'s licenses.', grades: [5], emoji: '🚗' },
      { id: 'soc45-constitution-18', type: 'mc', q: 'Which is a responsibility of citizens?', choices: ['Obeying the law', 'Never reading the news', 'Ignoring jury duty'], answer: 0, hint: 'Responsibilities help a community work well.', explain: 'Citizens are responsible for obeying laws, serving on juries and staying informed.', grades: [5], emoji: '🙋' },
      { id: 'soc45-constitution-19', type: 'mc', q: 'How old must US citizens be to vote?', choices: ['16', '18', '21', '25'], answer: 1, hint: 'It is the age when most people finish high school.', explain: 'Citizens can vote at age 18.', grades: [5], emoji: '🗳️' },
      { id: 'soc45-constitution-20', type: 'mc', q: 'What are the first three words of the Constitution?', choices: ['Once upon a time', 'Four score and', 'We the People'], answer: 2, hint: 'They show that the government belongs to everyone.', explain: 'The Constitution begins, "We the People."', grades: [5], emoji: '📜' },
      { id: 'soc45-constitution-21', type: 'mc', q: 'What is an amendment?', choices: ['A branch of government', 'A kind of court', 'A change or addition to the Constitution'], answer: 2, hint: 'To "amend" something means to change or improve it.', explain: 'An amendment is a change or addition to the Constitution.', grades: [5], emoji: '➕' },
    ],
  },

  // ───────────────────────── GRADE 5: US GEOGRAPHY ─────────────────────────
  { id: 'soc45-geography5', name: 'States & Geography', icon: '🧭', desc: 'States, capitals, rivers & mountains', grades: [5],
    learn: [
      { emoji: '🏛️', text: 'The US has 50 states. The nation\'s capital is Washington, D.C., which is not part of any state. Each state has its own capital city where its government meets.' },
      { emoji: '📍', text: 'A capital is not always the biggest city. California: Sacramento. Texas: Austin. New York: Albany. Florida: Tallahassee. Illinois: Springfield. Pennsylvania: Harrisburg.' },
      { emoji: '🗺️', text: 'A physical map shows landforms and water, like mountains, plains and rivers. A political map shows borders, states, cities and capitals.' },
      { emoji: '🌊', text: 'Major rivers: the Mississippi (flows into the Gulf of Mexico), the Missouri and the Ohio (both flow into the Mississippi), the Colorado (carved the Grand Canyon), the Columbia (Pacific Northwest) and the Rio Grande (part of the border with Mexico).' },
      { emoji: '🏔️', text: 'Major mountains: the Rockies, where the Continental Divide separates rivers flowing west from rivers flowing east; the Appalachians in the East; the Sierra Nevada in California; and the Cascades in Washington and Oregon, with volcanoes like Mount St. Helens.' },
      { emoji: '🚢', text: 'People settled near rivers, coasts and harbors for water, food, travel and trade. New Orleans grew near the mouth of the Mississippi. Mountains were barriers; the Cumberland Gap was a pass through the Appalachians.' },
      { emoji: '📐', text: 'Alaska is the largest state; Rhode Island is the smallest. Examples by region: Maine (Northeast), Georgia (Southeast), Ohio (Midwest), Arizona (Southwest), Oregon (West).' },
    ],
    questions: [
      { id: 'soc45-geography5-01', type: 'mc', q: 'What is the capital of California?', choices: ['Los Angeles', 'Sacramento', 'San Francisco'], answer: 1, hint: 'Remember, the capital is not always the biggest or most famous city.', explain: 'Sacramento is California\'s capital.', grades: [5], emoji: '🌉' },
      { id: 'soc45-geography5-02', type: 'mc', q: 'What is the capital of Texas?', choices: ['Houston', 'Dallas', 'Austin'], answer: 2, hint: 'It is in central Texas, not on the Gulf coast.', explain: 'Austin is the capital of Texas.', grades: [5], emoji: '🤠' },
      { id: 'soc45-geography5-03', type: 'mc', q: 'What is the capital of New York State?', choices: ['Albany', 'New York City', 'Buffalo'], answer: 0, hint: 'It is a smaller city up the Hudson River.', explain: 'Albany is New York\'s capital.', grades: [5], emoji: '🗽' },
      { id: 'soc45-geography5-04', type: 'mc', q: 'What is the capital of Florida?', choices: ['Miami', 'Orlando', 'Tallahassee'], answer: 2, hint: 'It is in the northern part of the state, not the far south.', explain: 'Tallahassee is Florida\'s capital.', grades: [5], emoji: '🌴' },
      { id: 'soc45-geography5-05', type: 'mc', q: 'What is the capital of Illinois?', choices: ['Springfield', 'Chicago', 'Peoria'], answer: 0, hint: 'It is in the middle of the state, where Abraham Lincoln lived before he became president.', explain: 'Springfield is the capital of Illinois.', grades: [5], emoji: '🌽' },
      { id: 'soc45-geography5-06', type: 'mc', q: 'What is the capital of Pennsylvania?', choices: ['Philadelphia', 'Pittsburgh', 'Harrisburg'], answer: 2, hint: 'It is not one of the two biggest cities.', explain: 'Harrisburg is Pennsylvania\'s capital.', grades: [5], emoji: '🔔' },
      { id: 'soc45-geography5-07', type: 'mc', q: 'What is the capital of the United States?', choices: ['New York City', 'Washington, D.C.', 'Philadelphia'], answer: 1, hint: 'It is named after the first president.', explain: 'Washington, D.C. is the nation\'s capital.', grades: [5], emoji: '🏛️' },
      { id: 'soc45-geography5-08', type: 'mc', q: '{name} wants to see where mountains and rivers are. Which kind of map is best?', choices: ['A political map', 'A physical map'], answer: 1, hint: 'Which map shows the shape of the land itself?', explain: 'A physical map shows landforms and bodies of water.', grades: [5], emoji: '⛰️' },
      { id: 'soc45-geography5-09', type: 'mc', q: 'Which kind of map shows state borders, cities and capitals?', choices: ['A political map', 'A physical map'], answer: 0, hint: 'This map is about places people govern.', explain: 'A political map shows borders, cities and capitals.', grades: [5], emoji: '🗺️' },
      { id: 'soc45-geography5-10', type: 'mc', q: 'Which is the largest state by area?', choices: ['Texas', 'California', 'Alaska'], answer: 2, hint: 'This state is far to the northwest and is not connected to the other 48.', explain: 'Alaska is by far the largest state.', grades: [5], emoji: '🐻' },
      { id: 'soc45-geography5-11', type: 'mc', q: 'Which is the smallest state?', choices: ['Rhode Island', 'Delaware', 'Connecticut'], answer: 0, hint: 'It is in New England, even though its name says "island."', explain: 'Rhode Island is the smallest state.', grades: [5], emoji: '🔍' },
      { id: 'soc45-geography5-12', type: 'mc', q: 'Which river carved the Grand Canyon?', choices: ['Hudson River', 'Mississippi River', 'Colorado River'], answer: 2, hint: 'The Grand Canyon is in Arizona, in the Southwest.', explain: 'The Colorado River carved the Grand Canyon over millions of years.', grades: [5], emoji: '🏜️' },
      { id: 'soc45-geography5-13', type: 'mc', q: 'Which river forms part of the border between Texas and Mexico?', choices: ['Rio Grande', 'Ohio River', 'Columbia River'], answer: 0, hint: 'It flows along the southwestern edge of Texas.', explain: 'The Rio Grande forms part of the US-Mexico border.', grades: [5], emoji: '🌊' },
      { id: 'soc45-geography5-14', type: 'mc', q: 'The Sierra Nevada mountains are mostly in which state?', choices: ['Florida', 'California', 'Ohio'], answer: 1, hint: 'These mountains are near the Pacific coast.', explain: 'The Sierra Nevada runs through eastern California.', grades: [5], emoji: '🏔️' },
      { id: 'soc45-geography5-15', type: 'mc', q: 'Mount St. Helens, a volcano that erupted in 1980, is in which mountain range?', choices: ['Appalachian Mountains', 'Ozark Mountains', 'Cascade Range'], answer: 2, hint: 'This range is in Washington and Oregon.', explain: 'Mount St. Helens is in the Cascade Range in Washington.', grades: [5], emoji: '🌋' },
      { id: 'soc45-geography5-16', type: 'mc', q: 'Why did many early towns grow up beside rivers?', choices: ['Rivers are always warm', 'Rivers keep the rain away', 'Rivers provide water, food and a way to move goods'], answer: 2, hint: 'Think about drinking, fishing and boats.', explain: 'Rivers gave settlers water, food, transportation and trade routes.', grades: [5], emoji: '🛶' },
      { id: 'soc45-geography5-17', type: 'mc', q: 'New Orleans became a busy port because it sits near where the ___ River meets the Gulf of Mexico.', choices: ['Mississippi', 'Colorado', 'Columbia'], answer: 0, hint: 'This is the river that flows south through the middle of the country.', explain: 'New Orleans is near the mouth of the Mississippi River.', grades: [5], emoji: '⚓' },
      { id: 'soc45-geography5-18', type: 'mc', q: 'Why was the Cumberland Gap important to early settlers?', choices: ['It was a harbor in Boston', 'It was a pass through the Appalachian Mountains', 'It was a bridge over the Pacific'], answer: 1, hint: 'A "gap" is an opening between high places.', explain: 'The Cumberland Gap let settlers cross the Appalachians to move west.', grades: [5], emoji: '🥾' },
      { id: 'soc45-geography5-19', type: 'mc', q: 'The Continental Divide, which separates rivers flowing west from rivers flowing east, runs along which mountains?', choices: ['Rocky Mountains', 'Appalachian Mountains', 'Ozark Mountains'], answer: 0, hint: 'It runs along the tallest mountains in the western US.', explain: 'The Continental Divide runs along the Rocky Mountains.', grades: [5], emoji: '🏔️' },
      { id: 'soc45-geography5-20', type: 'mc', q: 'Which state is in the Southeast?', choices: ['Oregon', 'Ohio', 'Georgia'], answer: 2, hint: 'Look in the lower right part of a US map.', explain: 'Georgia is in the Southeast.', grades: [5], emoji: '🍑' },
      { id: 'soc45-geography5-21', type: 'mc', q: 'Which state is in the West region?', choices: ['Maine', 'Alabama', 'Oregon'], answer: 2, hint: 'Find the state on the Pacific coast.', explain: 'Oregon is in the West.', grades: [5], emoji: '🌲' },
    ],
  }
);
